-- ============================================================================
--  smt_db.sql - Shin Megami Tensei (SMT1): banco de dados pronto para uso
-- ----------------------------------------------------------------------------
--  Conteudo : 244 demonios, 105 skills, 3.416 resistencias, 689 skills inatas,
--             37 racas, 13 species, 19 elementos, 239 celulas do chart de fusao
--             raca x raca, 224 celulas do chart de species (grupo), 152 linhas
--             do element chart, 28 pares de elementais, 49 receitas especiais
--             e 13.985 fusoes pre-calculadas.
--  Origem   : dados do site/megaten-fusion-tool (aqiu384) - commit master
--  Gerado   : mysqldump (MariaDB 11.8) a partir de schema.sql + import.php
--
--  Como usar:
--     mysql -u root -p < smt_db.sql          (linha de comando)
--     phpMyAdmin: Importar > escolher o arquivo > Executar
--
--  ATENCAO: o script recria o banco `smt_db` (DROP DATABASE + CREATE DATABASE),
--  substituindo qualquer versao anterior. As tabelas de party sao recriadas
--  vazias - exporte as suas antes, se necessario.
--
--  Observacoes:
--    * Este dump ja reflete a revisao final: NAO existe a coluna
--      `demons.fusion_kind` (ela era derivavel e foi removida; o tipo de
--      obtencao - fusao / receita_especial / recrutamento / inimigo - e
--      calculado pela API a partir das tabelas de fusao e de receitas).
--    * Bases criadas antes dessa revisao se atualizam com
--      db/migrate_004_drop_fusion_kind.sql.
--
--  Para regerar tudo a partir da fonte:  php import.php --user=root --pass=...
-- ============================================================================

