/*!40000 ALTER TABLE `demon_skills` ENABLE KEYS */;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;
DROP TABLE IF EXISTS `demons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `demons` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(60) NOT NULL COMMENT 'Identificador para URL (ex.: baek-young)',
  `name` varchar(60) NOT NULL,
  `race_id` smallint(5) unsigned NOT NULL,
  `level` decimal(4,1) NOT NULL COMMENT 'Nível do demônio. Pode ter casa decimal (ex.: 55.1) quando o site usa o nível como critério de desempate nas fusões; a ficha exibe o valor como está',
  `align_code` char(2) NOT NULL COMMENT 'Alinhamento do demônio (normalmente igual ao da raça)',
  `alignment` enum('Law','Neutral','Chaos') NOT NULL,
  `drop_item` varchar(40) DEFAULT NULL COMMENT 'Item dropado (NULL = nenhum)',
  `hp` smallint(5) unsigned NOT NULL,
  `mp` smallint(5) unsigned NOT NULL,
  `cp` tinyint(3) unsigned NOT NULL COMMENT 'CP exibido na ficha',
  `strength` tinyint(3) unsigned NOT NULL COMMENT 'St',
  `intelligence` tinyint(3) unsigned NOT NULL COMMENT 'In',
  `magic` tinyint(3) unsigned NOT NULL COMMENT 'Ma',
  `vitality` tinyint(3) unsigned NOT NULL COMMENT 'Vi',
  `agility` tinyint(3) unsigned NOT NULL COMMENT 'Ag',
  `luck` tinyint(3) unsigned NOT NULL COMMENT 'Lu',
  `natk` smallint(5) unsigned NOT NULL COMMENT 'NAtk - ataque físico base',
  `nmin` tinyint(3) unsigned NOT NULL COMMENT 'NMin - número mínimo de golpes',
  `nmax` decimal(3,1) NOT NULL COMMENT 'NMax - número máximo de golpes (aceita fração, ex.: 0.8)',
  `patk` smallint(5) unsigned NOT NULL COMMENT 'PAtk - poder físico',
  `phit` tinyint(3) unsigned NOT NULL COMMENT 'PHit - acerto físico',
  `defense` tinyint(3) unsigned NOT NULL COMMENT 'Def',
  `evasion` tinyint(3) unsigned NOT NULL COMMENT 'Eva',
  `matk` tinyint(3) unsigned NOT NULL COMMENT 'MAtk - poder mágico',
  `mhit` tinyint(3) unsigned NOT NULL COMMENT 'MHit - acerto mágico',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_demons_name` (`name`),
  UNIQUE KEY `uq_demons_slug` (`slug`),
  KEY `idx_demons_race_lvl` (`race_id`,`level`),
  KEY `idx_demons_level` (`level`),
  CONSTRAINT `fk_demons_race` FOREIGN KEY (`race_id`) REFERENCES `races` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=245 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Os 244 demônios do jogo: nível, raça, atributos e parâmetros de combate';
/*!40101 SET character_set_client = @saved_cs_client */;

SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
/*!40000 ALTER TABLE `demons` DISABLE KEYS */;
