CREATE TABLE `fusion_chart` (
  `race_a_id` smallint(5) unsigned NOT NULL,
  `race_b_id` smallint(5) unsigned NOT NULL,
  `result_type` enum('race','species','element_demon') NOT NULL COMMENT 'O cruzamento gera: uma raça, um grupo (species) ou um elemental específico',
  `result_race_id` smallint(5) unsigned DEFAULT NULL,
  `result_species_id` tinyint(3) unsigned DEFAULT NULL,
  `result_demon_id` smallint(5) unsigned DEFAULT NULL,
  PRIMARY KEY (`race_a_id`,`race_b_id`),
  KEY `idx_fc_result_race` (`result_race_id`),
  KEY `idx_fc_result_species` (`result_species_id`),
  KEY `idx_fc_result_demon` (`result_demon_id`),
  KEY `fk_fc_race_b` (`race_b_id`),
  CONSTRAINT `fk_fc_race_a` FOREIGN KEY (`race_a_id`) REFERENCES `races` (`id`),
  CONSTRAINT `fk_fc_race_b` FOREIGN KEY (`race_b_id`) REFERENCES `races` (`id`),
  CONSTRAINT `fk_fc_res_de` FOREIGN KEY (`result_demon_id`) REFERENCES `demons` (`id`),
  CONSTRAINT `fk_fc_res_ra` FOREIGN KEY (`result_race_id`) REFERENCES `races` (`id`),
  CONSTRAINT `fk_fc_res_sp` FOREIGN KEY (`result_species_id`) REFERENCES `species` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Chart de fusão normal raça x raça: 239 células preenchidas do chart do site (224 pares + 15 de mesma raça, que geram o elemental). Par normalizado: race_a_id < race_b_id';
/*!40101 SET character_set_client = @saved_cs_client */;

