DROP TABLE IF EXISTS `parties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `parties` (
  `id` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL COMMENT 'Nome dado pelo jogador à party',
  `protagonist_name` varchar(40) DEFAULT NULL COMMENT 'Nome do personagem do jogador',
  `protagonist_level` tinyint(3) unsigned NOT NULL DEFAULT 1 COMMENT 'Nível do protagonista (1 a 99)',
  `protagonist_alignment` enum('Law','Neutral','Chaos') DEFAULT NULL COMMENT 'Alinhamento do protagonista; no SMT1 ele afeta negociação e fusão',
  `comp_upgraded` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 = COMP inicial (3 demônios convocados); 1 = atualizado por Stephen (4 demônios)',
  `human_partners` varchar(80) DEFAULT NULL COMMENT 'Parceiros humanos na formação, texto livre (Law Hero, Chaos Hero, Heroína)',
  `notes` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_parties_name` (`name`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Party do SMT1: protagonista (nome, nível, alinhamento) + até 5 demônios. comp_upgraded guarda o limite 3->4 do jogo';
/*!40101 SET character_set_client = @saved_cs_client */;

